package com.networkers.meetingautomation;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="monthly_meetings") public class MonthlyMeeting { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @OneToOne(optional=false) private MeetingGroup group; private LocalDate scheduledDate; private LocalTime scheduledTime; private String venue; private int editCount; private int maxEdits=2; private boolean reminderSent; @Enumerated(EnumType.STRING) private AutomatedMeetingStatus status=AutomatedMeetingStatus.UPCOMING; private LocalDateTime updatedAt; @PrePersist @PreUpdate void touch(){updatedAt=LocalDateTime.now();} public Long getId(){return id;} public MeetingGroup getGroup(){return group;} public void setGroup(MeetingGroup v){group=v;} public LocalDate getScheduledDate(){return scheduledDate;} public void setScheduledDate(LocalDate v){scheduledDate=v;reminderSent=false;} public LocalTime getScheduledTime(){return scheduledTime;} public void setScheduledTime(LocalTime v){scheduledTime=v;} public String getVenue(){return venue;} public void setVenue(String v){venue=v;} public int getEditCount(){return editCount;} public void setEditCount(int v){editCount=v;} public int getMaxEdits(){return maxEdits;} public boolean isReminderSent(){return reminderSent;} public void setReminderSent(boolean v){reminderSent=v;} public AutomatedMeetingStatus getStatus(){return status;} public void setStatus(AutomatedMeetingStatus v){status=v;} public LocalDateTime getUpdatedAt(){return updatedAt;} }
